"""Mock data for the panel preview, generated by the real backend.

`tests/frontend/fixtures.json` is what the panel receives from `tariffy/contracts`
for a set of realistic contracts. This test rebuilds it with the real coordinator
and fails if the checked-in file is out of date, so the frontend mock cannot drift
from the backend. Regenerate with:  UPDATE_FIXTURES=1 pytest tests/test_panel_fixtures.py
"""

from __future__ import annotations

import json
import os
from pathlib import Path
from unittest.mock import patch

from homeassistant.core import HomeAssistant
from pytest_homeassistant_custom_component.common import MockConfigEntry

from custom_components.tariffy import panel
from custom_components.tariffy.const import DOMAIN

